function UIWindowLoginDialog:OnBtnReturn()
    local time = os.time()
    local url = GameUtils:GetWinSdkUrl() .. "/?time=" .. os.time()
    if self._go then
        if self._IsUsedVuplexWebView then
            self._go:LoadURL(url, true)
        else
            self._go:Load(url)
        end
    else
        GameUtils.Toast('[warn] WebView is null !!')
    end

    self:SetSelfPageStatus(false)
    --CfUtils.SetActive(self.BtnClose, false)
end

function UIWindowLoginDialog:OnBtnBack()
    if not self._go then
        GameUtils.Toast('[warn] WebView is null !!')
        return
    end
    if self._IsUsedVuplexWebView then
        if self._go.CanGoBack then
            self._go:GoBack()
        end
    else
        if self._go.UniWebView.CanGoBack then
            self._go.UniWebView:GoBack()
        end
    end
end

function UIWindowLoginDialog:OnBtnForward()
    if not self._go then
        GameUtils.Toast('[warn] WebView is null !!')
        return
    end
    if self._IsUsedVuplexWebView then
        if self._go.CanGoForward then
            self._go:GoForward()
        end
    else
        if self._go.UniWebView.CanGoForward then
            self._go.UniWebView:GoForward()
        end
    end
end

function UIWindowLoginDialog:OnBtnRefresh()
    if self._go then
        if self._IsUsedVuplexWebView then
            self._go:Reload()
        else
            self._go.UniWebView:Reload()
        end
    else
        GameUtils.Toast('[warn] WebView is null !!')
    end
end

