function UIWindowLoginDialog:OnWinSDK(body)
    if not body then
        return
    end
    local type = checkNumber(body.type)
    self:PrintLog('event', string.format('type = %d', type))

    --登录
    if type == POSTTYPE.Login then
        self._sdkType = SDKTYPE.Login
        self._isLoginSuccess = false

        if GameUtils.IsSteam() then
            if not self._isInit then
                self._isInit = true
                KTool.SetActive(self.CanvasWebViewPrefab.gameObject, false)
                KTool.SetActive(self.SteamManager.gameObject, true)
                if self.steamCo ~= nil then
                    cs_coroutine.stop(self.steamCo)
                end
                self.steamCo = cs_coroutine.start(self.LoginSteam, self)
            else
                --初始化完成的话发消息给打开登录
                local t = {
                    ErrorCode = POSTTYPE.Login,
                    Msg = ""
                }
                self:PostWebMessage(t)
            end
        else

            --初始化一次
            if not self._isInit then
                self._isInit = true
                self:InitWebView()
