--发送消息
function UIWindowLoginDialog:PostWebMessage(data)
    if not data or isNull(self._go) or not self._isInit then
        return
    end
    local str = table.serialize(data)
    self:PrintLog('post', string.format('%s', str))

    if self._IsUsedVuplexWebView then
        self._go:CallStringFunction("MessageEmittedGame", str):Done()
    else
        local commandString = string.format('MessageEmittedGame(%s);', string.url_decode(str))
        ---@param payload UniWebViewNativeResultPayload
        self._go.UniWebView:EvaluateJavaScript(commandString, function(payload)
            if checkInt(payload.resultCode) == 0 then
            else
                self:PrintLog('post', string.format('error: code = %d, data = %s', checkInt(payload.resultCode), tostring(payload.data)))
            end
        end)
    end

    --self:ExecuteJavaScript("MessageEmittedGame(\"" .. str .."\")")
    print(str)
end

function UIWindowLoginDialog:CallFunction(cmd, str)
    if not str or isNull(self._go) or not self._isInit then
        return
    end

    self:PrintLog('call', string.format('%s | %s', tostring(cmd), tostring(str)))
    self._go:CallStringFunction(cmd, str):Done()
    --self._go:ExecuteJavaScript("javascript:" .. str)
    print(str)
end



