    --KTool.SetParent(self._go.gameObject, self.ViplexWebViewNode.gameObject, false)
    ---@type ZenFulcrum.EmbeddedBrowser.Browser | Engine.Modules.WebView
    self._go = self.CanvasWebViewPrefab
