    --end
    --self._go:Init()

    print(self._go)

    local time = os.time()
    local url = GameUtils:GetWinSdkUrl() .. "/?time=" .. os.time()
    self:PrintLog('init', string.format('open = %s', url))

    if self._IsUsedVuplexWebView then
        self._go:LoadURL(url, true)
    else
        self._go:Load(url)
