--                 }
--                 MessageEmittedWeb(data)
--             }
--         </script>
--     </body>
-- </html>
--     ]]
--         self._go:LoadHTMLString(url)
    end

    local initFinishCb = function()
        if KCookie.Get("GAME_BACK_TO_LOGIN") then
            local t = {
                ErrorCode = SDKService:isIndo() and POSTTYPE.MAJO_SwitchLogin or POSTTYPE.SwitchLogin,
                Msg = self:GetInitMeg(),
            }
            self:PostWebMessage(t)
            print("SwitchLogin~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~")
        else
            local t = {
                ErrorCode = SDKService:isIndo() and POSTTYPE.MAJO_Init or POSTTYPE.Init,
                Msg = self:GetInitMeg(),
            }
            self:PostWebMessage(t)
            print("FirstLogin~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~")
        end
    end

    local eventCb = function(args)
        local nurl = checkString(args:Get("url").Value)
        self:PrintLog('init', string.format('loaded = %s', nurl))

        if self._IsUsedVuplexWebView then
            self._go:RegisterFunction("MessageEmittedWeb", function(sender)
                if sender.Count > 0 then
                    self:PrintLog('handle', string.format('data = %s', tostring(sender[0].AsJSON)))
                    local data = self:DeserializeData(sender[0].AsJSON)
                    self:HandleEvent(data)
                end
            end)
        else
            local jsString = [[
                function MessageEmittedWeb(data) { 
                    location.href = "uniwebview://MessageEmittedWeb?json=" + encodeURIComponent(JSON.stringify(data)); 
                }
            ]]
            ---@param payload UniWebViewNativeResultPayload
            self._go.UniWebView:AddJavaScript(jsString, function(payload)
                self:PrintLog('regist', string.format('<MessageEmittedWeb> : %s', tostring(payload.resultCode)))
            end)
            ---@param message UniWebViewMessage
            self._go._onReceivedMessage = function(message)
                if message.Path == "MessageEmittedWeb" then
                    local ret, jsonStr = message.Args:TryGetValue("json")
                    self:PrintLog('handle', string.format('data = %s', tostring(jsonStr)))
                    if not string.isEmpty(jsonStr) then
                        local data = self:DeserializeData(jsonStr)
                        self:HandleEvent(data)
                    end
                end
            end
            if self._IsUniWebViewShowing then
                return
            end
            self._go:Show({fade = false, finishAction = function()
                initFinishCb()
                self._go.UniWebView:SetSize(2560, 1440)
                self._go.UniWebView:SetPosition(1760, -720)
                self._IsUniWebViewShowing = true
            end})
        end
        --	local i,_ = string.find(nurl,"https://www.sandbox.paypal.com/checkoutweb/signup")
        --	local j,_ = string.find(nurl,"https://www.paypal.com/checkoutweb/signup")
        --	if i ~= nil or j ~= nil then
        --		self._go:EvalJSCSP("document.body.style.background = 'white'"):Done()
        --	end
        --	local k,_ = string.find(nurl,"https://appleid.apple.com")
        --	if k ~= nil then
        --		KTool.SetActive(self.WhiteBackground.gameObject, true)
        --	else
        --		KTool.SetActive(self.WhiteBackground.gameObject, false)
        --	end
    end

    if self._IsUsedVuplexWebView then
        initFinishCb()
        self._go:onLoad('+', eventCb)
    else
        self._go._onLoadComplete = function()
            local argsObj = { url = self._go.UniWebView.Url }
            function argsObj:Get(key)
                return {Value = argsObj[key]}
            end
            eventCb(argsObj)
        end
    end

    local eventStateChange = function()
        if self._go.Url == "" then
            return
        end
        self:PrintLog('state', string.format('change = %s', tostring(self._go.Url)))

        local sdkUrl = GameUtils:GetWinSdkUrl2()
        if string.sub(self._go.Url, 1, string.len(sdkUrl)) == sdkUrl then
            CfUtils.SetActive(self.BrowserToolbar, false)
            self.ViplexWebViewNode.anchoredPosition = CS.UnityEngine.Vector2(0, -540)
            self.ViplexWebViewNode:SetSizeWithCurrentAnchors(CS.UnityEngine.RectTransform.Axis.Vertical, 1080)
            KTool.SetActive(self.WhiteBackground.gameObject, false)
        else
            CfUtils.SetActive(self.BrowserToolbar, true)
            self.ViplexWebViewNode.anchoredPosition = CS.UnityEngine.Vector2(0, -570)
            self.ViplexWebViewNode:SetSizeWithCurrentAnchors(CS.UnityEngine.RectTransform.Axis.Vertical, 1020)
            KTool.SetActive(self.WhiteBackground.gameObject, true)
        end

        CfUtils.SetActive(self.BackButton, self._go.CanGoBack)
        CfUtils.SetActive(self.ForwardButton, self._go.CanGoForward)

    end

    if self._IsUsedVuplexWebView then
        self._go:onNavStateChange('+', eventStateChange)
    end

    local eventErrorCb = function(args)
        self:SetSelfPageStatus(false)
        local nurl = checkString(args:Get("url").Value)
        local sdkUrl = GameUtils:GetWinSdkUrl()
        self:PrintLog('init', string.format('error = %s', nurl))

        if string.sub(nurl, 1, string.len(sdkUrl)) == sdkUrl then
            if self.co ~= nil then
                cs_coroutine.stop(self.co)
            end
            self.co = cs_coroutine.start(self.ReInitWebView, self)
        end
    end

    if self._IsUsedVuplexWebView then
        self._go:onFetchError('+', eventErrorCb)

        self._go:onCertError('+', eventErrorCb)

    else
        local uniErrorCb = function(uniWebView, errorCode, errorMsg)
            local argsObj = { url = uniWebView.Url }
            function argsObj:Get(key)
                return {Value = argsObj[key]}
            end
            eventErrorCb(argsObj)
        end
        self._go._onLoadError = function(errorCode, errorMsg)
            uniErrorCb(self._go, errorCode, errorMsg)
        end
        ---@param uniWebView UniWebView
        ---@param errorCode integer
        ---@param errorMsg string
        -- self._go.UniWebView.OnPageErrorReceived('+', function(uniWebView, errorCode, errorMsg)
        --     uniErrorCb(uniWebView.Url, errorCode, errorMsg)
        -- end)
    end


    --CS.ZenFulcrum.EmbeddedBrowser.Browser.onAnyBrowserCreated('+', eventCb)
    -- self._go:onAnyBrowserCreated('+', eventCb)

    self:SetSelfPageStatus(true)
end

function UIWindowLoginDialog:ReInitWebView()
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(3))
    self.co = nil
    self:InitWebView()
end

