--设置当前页面的状态
function UIWindowLoginDialog:SetSelfPageStatus(isShow)
    --[[
    KTool.SetActive(self.EmptyBg, isShow)
    if isShow then
        self.Container.alpha = 1
    else
        self.Container.alpha = 0
    end
    ]]

    -- 界面隐藏后无法收到 SDK 消息，这里界面不隐藏，仅设置 canvas 和 graphicRaycaster 以解决界面阻挡点击的问题
    if isShow then
        KTool.SetActive(self.controller.gameObject, isShow)
    end

    local canvas = KTool.GetComponent(self.controller.gameObject, typeof(CS.UnityEngine.Canvas))
    local graphicRaycaster = KTool.GetComponent(self.controller.gameObject, typeof(CS.UnityEngine.UI.GraphicRaycaster))
    canvas.enabled = isShow
    graphicRaycaster.enabled = isShow

    self.controller.gameObject.transform:SetAsLastSibling()
end

--激活事件
function UIWindowLoginDialog:HandleEvent(data)
    if isNull(data) then
        return
    end
    print(table.dump(data))
    --登录成功
    if data.ErrorCode == Constants.SdkErrorCode.LoginSuccess then
        if not self._isLoginSuccess then
            local SDKService = import('Game.Entry.SDKService')
            SDKService:GetInstance():__SDKHandler(clone(data.ErrorCode), clone(data.Msg))
            self._isLoginSuccess = true
            self:SetSelfPageStatus(false)
            CfUtils.WriteAutoLoginData2(checkString(data.Msg))
            self._loginMsg = table.deserialize(checkString(data.Msg))
            CfUtils.CookieSave('WebLoginMsg', self._loginMsg)
            logt(self._loginMsg, "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~")
        end
        --收到初始化成功之后参数抛出去   loadurl中会异常
    elseif data.ErrorCode == Constants.SdkErrorCode.InitSuccess then
        local t = {
            ErrorCode = POSTTYPE.Init,
            Msg = self:GetInitMeg(),
        }
        self:PostWebMessage(t)
        --这个类型直接关掉当前界面
    elseif data.ErrorCode == Constants.SdkErrorCode.InitFail then
        --UIModule.CloseDialog(self.controller)
        self:SetSelfPageStatus(false)
        --win实名
    elseif data.ErrorCode == Constants.SdkErrorCode.RealName then
        self:FillRealNameNode()
        --进入游戏
    elseif data.ErrorCode == Constants.SdkErrorCode.EnterGame then
        self:SetSelfPageStatus(false)
        Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_ENTER_GAME, data = {} })
        --防成谜时间到了
    elseif data.ErrorCode == Constants.SdkErrorCode.AntiAddictionTime then
        self:SetSelfPageStatus(true)
    elseif data.ErrorCode == Constants.SdkErrorCode.PayProdustList then
        local SDKService = import('Game.Entry.SDKService')
        SDKService:GetInstance():__SDKHandler(clone(data.ErrorCode), clone(data.Msg))
        --杀进程
    elseif data.ErrorCode == Constants.SdkErrorCode.KickOut then
        local SDKService = import('Game.Entry.SDKService')
        SDKService:GetInstance():__SDKHandler(clone(data.ErrorCode), clone(data.Msg))
        --CS.UnityEngine.Application.Quit()
    elseif data.ErrorCode == Constants.SdkErrorCode.PaySuccess then
        local SDKService = import('Game.Entry.SDKService')
        SDKService:GetInstance():__SDKHandler(clone(data.ErrorCode), clone(data.Msg))
        self:SetSelfPageStatus(false)
    elseif data.ErrorCode == Constants.SdkErrorCode.PayFail then
        self:SetSelfPageStatus(false)
    elseif data.ErrorCode == Constants.SdkErrorCode.DelAccount then
        CfUtils.WriteAutoLoginData2(checkString(data.Msg))
    elseif data.ErrorCode == Constants.SdkErrorCode.LogoutFinish then
        CfUtils.WriteAutoLoginData2(checkString(data.Msg))
        self:SetSelfPageStatus(false)
        Events.Broadcast("SDKLOGOUT", {})
        Events.Broadcast(Constants.EventNames.WinSDK, { type = 2 })
    elseif data.ErrorCode == POSTTYPE.WriteLocalData then
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        local openId = ""
        if userComponent then
            openId = tostring(userComponent.userInfo.openId)
        end
        CfUtils.WriteWindowWebLocalData(checkString(data.CodeName), checkString(data.Msg), openId)
    elseif data.ErrorCode == POSTTYPE.GetSteamTicket then
        --print("~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~")
        --self._pchIdentity = tostring(CS.System.DateTime.Now.Ticks)
        --self._pchIdentity = tostring(CS.System.DateTime.Now.Ticks)
        --print(self._pchIdentity)
        --CS.Steamworks.SteamUser:GetAuthTicketForWebApi(self._pchIdentity)
        CS.FuntoySteamManager:SignInWithSteam()
        --print("~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~22222")
    elseif data.ErrorCode == POSTTYPE.OpenSteamPay then
        print("~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~90")
    elseif data.ErrorCode == POSTTYPE.RealAuthResult then
        local t = table.deserialize(data.Msg)
        if tonumber(t.has_real_auth) == 1 then
            self._loginMsg.has_real_auth = 1
            if self.IsStartGameCheck then
                Events.Broadcast("WinEnterGame", { type = 1 })
            else
                Events.Broadcast("WinPlayerCreateDialog", { type = 1 })
            end
        else
            self:SetSelfPageStatus(false)
        end
    elseif data.ErrorCode == Constants.SdkErrorCode.HealthTip then
        local SDKService = import('Game.Entry.SDKService')
        SDKService:GetInstance():__SDKHandler(clone(data.ErrorCode), clone(data.Msg))
        self:SetSelfPageStatus(false)
    elseif data.ErrorCode == POSTTYPE.OPEN_BROWSER then
        --打开网页
        local url = checkString(data.Msg)
        CfUtils.OpenURL(url)
    elseif checkNumber(data.ErrorCode) == Constants.SdkErrorCode.PayDMM_CALL_BACK_WEB then
        --dmm web callback
        SDKService:GetInstance():__SDKHandler(clone(data.ErrorCode), clone(data.Msg))
        self:SetSelfPageStatus(false)
    else
        GameUtils.Toast(table.dump(data))
    end
end

--绘制实名的节点
function UIWindowLoginDialog:FillRealNameNode()
    KTool.SetActive(self.RealName, true)
    SetButtonAction(self.BtnSure, function()
        --直接影藏 错误的h5返回Constants.SdkErrorCode.RealName
        KTool.SetActive(self.RealName, false)
        local name = self.InputName.text
        local idCard = self.InputIdCard.text
        local t = {
            ErrorCode = POSTTYPE.RealName,
            Msg = {
                Name = name,
                IdCard = idCard,
            }
        }
        self:PostWebMessage(t)
    end)
end

