--反序列化一份数据
function UIWindowLoginDialog:DeserializeData(data)
    if isNull(data) then
        return nil
    end
    local msg = table.deserialize(data)
    if not IsNull(msg.type) then
        return nil
    end
    local t = {
        ErrorCode = checkInt(msg.ErrorCode),
        Msg = msg.Msg,
        CodeName = msg.CodeName
    }
    return t
end

--init 初始化参数
function UIWindowLoginDialog:GetInitMeg()
    local t = {
        platform = "pc",
        channel = GameUtils.GetChannelId(),
        app_version_code = CS.Game.Native.Game.Instance.Version:ToStandardVersionString(),
        kid = CS.Engine.Http.HttpModule.RequestBodyMeta.DeviceId,
        idfa = CS.Engine.Http.HttpModule.RequestBodyMeta.IdFa,
        lang = CS.Engine.I18N.I18NModule.Lang,
        app_id = GameUtils.GetCurAppId(),
        isDMM = 0,
    }

    if GameUtils.GetChannelId() == DMM_CHANNEL_ID then
        ---@type UserComponent
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        ---@type UserDojo
        local userDojo = userComponent.userInfo
        table.merge(t, {
            isDMM = 1,
            viewId = userDojo.viewId,
            onetimeToken = userDojo.oneTimeAccessToken,
            dmmAccessToken = userDojo.dmmAccessToken,
        })
    end

    if self._SteamID ~= nil then
        t.steam_id = self._SteamID
    end

    local str = checkString(CfUtils.GetAutoLoginData2())
    print('>> AutoLoginData', str)
    if not string.isEmpty(str) then
        local data = table.deserialize(str)
        for k, v in pairs(data) do
            print('>> init args >>', k, v)
            t[k] = v
        end
    end

    return t
end



