function UIWindowLoginDialog:OnDestroy()
    Events.RemoveListener(Constants.EventNames.WinSDK, self.EventWinSDK)
    if self.co ~= nil then
        cs_coroutine.stop(self.co)
    end
    if self.steamCo ~= nil then
        cs_coroutine.stop(self.steamCo)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIWindowLoginDialog